import mongoose from 'mongoose';

/**
 * Notification — in-app reminder generated by the cron job or system events.
 *
 * user is referenced (not embedded) because:
 *  - Each user can accumulate hundreds of notifications over time; embedding inside
 *    the User document would cause unbounded growth.
 *  - Notifications are queried independently (unread count, paginated list).
 */
const notificationSchema = new mongoose.Schema(
  {
    user: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: true,
      index: true,
    },
    message: {
      type: String,
      required: [true, 'Notification message is required'],
    },
    type: {
      type: String,
      enum: ['service_due', 'document_expiry', 'system'],
      required: true,
    },
    isRead: {
      type: Boolean,
      default: false,
    },
    // Optional link back to the vehicle for deep-linking in the UI
    relatedVehicle: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Vehicle',
    },
  },
  { timestamps: true }
);

// Compound index: the bell icon frequently queries unread count per user
notificationSchema.index({ user: 1, isRead: 1 });

export default mongoose.model('Notification', notificationSchema);
